        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var foresight = last.foresightQuality || 0;
            var robustness = last.strategicRobustness || 0;
            var confidence = last.boardConfidence || 0;
            var optionValue = last.optionValue || 0;
            var npv = last.portfolioNPV || 0;
            var stranded = last.strandedRisk || 0;

            var composite = (foresight * 0.25) + (robustness * 0.35) + (confidence * 0.15) +
                            (Math.min(100, optionValue / 5) * 0.15) + (Math.max(0, 50 + npv / 20) * 0.1) -
                            (stranded / 20);

            var performance = `Developing`;
            if (composite > 70) performance = `Exemplary`;
            else if (composite > 55) performance = `Proficient`;

            var insights = [];
            if (robustness >= 70) insights.push(`Portfolio survived stress-testing across divergent scenarios — strong robustness.`);
            if (foresight >= 70) insights.push(`Scanning and scenario craft generated sharp weak-signal detection.`);
            if (optionValue >= 200) insights.push(`You embedded real optionality worth $` + Math.round(optionValue) + `M in reversible commitments.`);
            if (confidence >= 70) insights.push(`Board narrative landed: stakeholders trust the strategic direction.`);
            if (stranded >= 150) insights.push(`Watch stranded asset exposure — the current portfolio carries $` + Math.round(stranded) + `M at risk.`);
            if (robustness < 50) insights.push(`Strategy optimized for one future at the cost of others. Revisit robustness.`);
            if (optionValue < 80) insights.push(`Limited embedded flexibility — pivots will be costly if scenarios shift.`);
            if (!insights.length) insights.push(`Solid foundation. Push for greater differentiation between scenarios next cycle.`);

            return {
                totalProfit: Math.round(npv),
                foresight: Math.round(foresight),
                robustness: Math.round(robustness),
                optionValue: Math.round(optionValue),
                confidence: Math.round(confidence),
                stranded: Math.round(stranded),
                composite: Math.round(composite),
                performance: performance,
                insights: insights
            };
        }

        _updateBriefing(state) {
            var periodNum = state.currentPeriod || 1;
            var idx = Math.min(periodNum - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;
            var round = this.ROUNDS[idx];
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById(`briefingTitle`);
            var monthsEl = document.getElementById(`briefingMonths`);
            var textEl = document.getElementById(`briefingText`);
            var delivEl = document.getElementById(`briefingDeliverable`);
            var primLabelEl = document.getElementById(`primaryFocusLabel`);
            var secLabelEl = document.getElementById(`secondaryFocusLabel`);
            var primHelpEl = document.getElementById(`primaryFocusHelp`);
            var secHelpEl = document.getElementById(`secondaryFocusHelp`);
            var primarySel = document.getElementById(`primaryFocus`);
            var secondarySel = document.getElementById(`secondaryFocus`);

            var rKey = `r` + (idx + 1);
            if (titleEl) titleEl.textContent = t(`brief_title_` + rKey);
            if (monthsEl) monthsEl.textContent = t(`brief_months_` + rKey);
            if (textEl) textEl.textContent = t(`brief_text_` + rKey);
            if (delivEl) delivEl.textContent = t(`brief_deliv_` + rKey);
            if (primLabelEl) primLabelEl.textContent = t(`primary_focus_label_` + rKey);
            if (secLabelEl) secLabelEl.textContent = t(`secondary_focus_label_` + rKey);
            if (primHelpEl) primHelpEl.textContent = t(`primary_focus_help_` + rKey);
            if (secHelpEl) secHelpEl.textContent = t(`secondary_focus_help_` + rKey);

            if (primarySel) {
                this._populateSelect(primarySel, round.primaryOptions, round.defaultPrimary);
            }
            if (secondarySel) {
                this._populateSelect(secondarySel, round.secondaryOptions, round.defaultSecondary);
            }

            var commitInp = document.getElementById(`capitalCommit`);
            var reserveInp = document.getElementById(`optionalityReserve`);
            if (commitInp && (!commitInp.dataset || !commitInp.dataset.roundSet || commitInp.dataset.roundSet !== String(idx))) {
                commitInp.value = round.defaultCommit;
                commitInp.dataset.roundSet = String(idx);
            }
            if (reserveInp && (!reserveInp.dataset || !reserveInp.dataset.roundSet || reserveInp.dataset.roundSet !== String(idx))) {
                reserveInp.value = round.defaultReserve;
                reserveInp.dataset.roundSet = String(idx);
            }
        }

        _populateSelect(sel, options, defaultVal) {
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var sig = options.map(function(o) { return o.value; }).join(`|`);
            if (sel.dataset && sel.dataset.sig === sig) {
                for (var j = 0; j < sel.options.length; j++) {
                    sel.options[j].textContent = t(options[j].i18n);
                }
                return;
            }
            sel.innerHTML = ``;
            for (var i = 0; i < options.length; i++) {
                var opt = document.createElement(`option`);
                opt.value = options[i].value;
                opt.textContent = t(options[i].i18n);
                if (options[i].value === defaultVal) opt.selected = true;
                sel.appendChild(opt);
            }
            if (sel.dataset) sel.dataset.sig = sig;
        }

